package com.aditya.day13.restaurant; import jakarta.persistence.*; import java.util.*; @Entity public class MenuItem{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;UUID restaurantId;String name;double price;boolean available=true;public UUID getId(){return id;}public void setRestaurantId(UUID x){restaurantId=x;}public UUID getRestaurantId(){return restaurantId;}public void setName(String x){name=x;}public String getName(){return name;}public void setPrice(double x){price=x;}public double getPrice(){return price;}public boolean isAvailable(){return available;}public void setAvailable(boolean x){available=x;}}